import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void depthwise_vertical_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int64_t N,
    int64_t C,
    int64_t H,
    int64_t W,
    int64_t K,
    int64_t Ho,
    int64_t Wo,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    bool has_bias) {
    constexpr int TILE_H = 16;
    constexpr int TILE_W = 16;
    extern __shared__ unsigned char shared_storage[];
    scalar_t* shared_tile =
        reinterpret_cast<scalar_t*>(shared_storage);
    const int64_t oh0 =
        static_cast<int64_t>(blockIdx.y) * TILE_H + threadIdx.y;
    const int64_t oh1 = oh0 + TILE_H / 2;
    const int64_t ow =
        static_cast<int64_t>(blockIdx.x) * TILE_W + threadIdx.x;
    const int64_t nc = static_cast<int64_t>(blockIdx.z);
    const int64_t n = nc / C;
    const int64_t c = nc % C;
    if (n >= N) {
        return;
    }
    scalar_t acc0 = scalar_t(0);
    scalar_t acc1 = scalar_t(0);
    if (has_bias) {
        acc0 = bias[c];
        acc1 = bias[c];
    }
    if (stride == 1) {
        const int64_t effective_k = dilation * (K - 1) + 1;
        const int64_t smem_h = TILE_H + effective_k - 1;
        const int64_t smem_elems = smem_h * TILE_W;
        const int64_t tid =
            static_cast<int64_t>(threadIdx.y) * TILE_W + threadIdx.x;
        const int64_t x0 =
            static_cast<int64_t>(blockIdx.x) * TILE_W - padding;
        const int64_t y0 =
            static_cast<int64_t>(blockIdx.y) * TILE_H - padding;
        for (int64_t i = tid;
             i < smem_elems;
             i += (TILE_H / 2) * TILE_W) {
            const int64_t sy = i / TILE_W;
            const int64_t sx = i % TILE_W;
            const int64_t iy = y0 + sy;
            const int64_t ix = x0 + sx;
            scalar_t value = scalar_t(0);
            if (iy >= 0 && iy < H && ix >= 0 && ix < W) {
                const int64_t x_idx = ((n * C + c) * H + iy) * W + ix;
                value = x[x_idx];
            }
            shared_tile[i] = value;
        }
        __syncthreads();
        if (ow < Wo) {
            const int64_t local_y0 = threadIdx.y;
            const int64_t local_y1 = local_y0 + TILE_H / 2;
            const int64_t local_x = threadIdx.x;
            for (int64_t ky = 0; ky < K; ++ky) {
                const scalar_t w = weight[c * K + ky];
                acc0 += shared_tile[(local_y0 + ky * dilation) * TILE_W + local_x] * w;
                if (oh1 < Ho) {
                    acc1 += shared_tile[(local_y1 + ky * dilation) * TILE_W + local_x] * w;
                }
            }
            if (oh0 < Ho) {
                const int64_t out_idx0 = ((n * C + c) * Ho + oh0) * Wo + ow;
                out[out_idx0] = acc0;
            }
            if (oh1 < Ho) {
                const int64_t out_idx1 = ((n * C + c) * Ho + oh1) * Wo + ow;
                out[out_idx1] = acc1;
            }
        }
        return;
    }
    if (ow >= Wo) {
        return;
    }
    const int64_t ix = ow * stride - padding;
    if (ix >= 0 && ix < W) {
        for (int64_t ky = 0; ky < K; ++ky) {
            const int64_t w_idx = c * K + ky;
            const int64_t iy0 = oh0 * stride - padding + ky * dilation;
            if (oh0 < Ho && iy0 >= 0 && iy0 < H) {
                const int64_t x_idx0 = ((n * C + c) * H + iy0) * W + ix;
                acc0 += x[x_idx0] * weight[w_idx];
            }
            if (oh1 < Ho) {
                const int64_t iy1 = oh1 * stride - padding + ky * dilation;
                if (iy1 >= 0 && iy1 < H) {
                    const int64_t x_idx1 = ((n * C + c) * H + iy1) * W + ix;
                    acc1 += x[x_idx1] * weight[w_idx];
                }
            }
        }
    }
    if (oh0 < Ho) {
        const int64_t out_idx0 = ((n * C + c) * Ho + oh0) * Wo + ow;
        out[out_idx0] = acc0;
    }
    if (oh1 < Ho) {
        const int64_t out_idx1 = ((n * C + c) * Ho + oh1) * Wo + ow;
        out[out_idx1] = acc1;
    }

}
torch::Tensor depthwise_vertical_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32,
                "Only float32 inputs are supported");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32,
                "Only float32 weights are supported");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32,
                "Only float32 bias is supported");
    TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "weight must have shape [C, 1, K, 1]");
    TORCH_CHECK(weight.size(1) == 1 && weight.size(3) == 1,
                "weight must have shape [C, 1, K, 1]");
    TORCH_CHECK(weight.size(0) == x.size(1),
                "weight channel dimension must match x");
    TORCH_CHECK(bias.numel() == 0 || bias.numel() == x.size(1),
                "bias must be empty or have one value per channel");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(dilation > 0, "dilation must be positive");
    TORCH_CHECK(padding >= 0, "padding must be non-negative");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    const int64_t N = x_c.size(0);
    const int64_t C = x_c.size(1);
    const int64_t H = x_c.size(2);
    const int64_t W = x_c.size(3);
    const int64_t K = w_c.size(2);

    const int64_t effective_k = dilation * (K - 1) + 1;
    const int64_t Ho = (H + 2 * padding - effective_k) / stride + 1;
    const int64_t Wo = (W + 2 * padding - 1) / stride + 1;

    TORCH_CHECK(Ho >= 0 && Wo >= 0, "Invalid output dimensions");

    auto out = torch::empty({N, C, Ho, Wo}, x_c.options());

    const int64_t total = N * C * Ho * Wo;
    if (total == 0) {
        return out;
    }

    constexpr int TILE_H = 16;
    constexpr int TILE_W = 16;
    const dim3 threads(TILE_W, TILE_H / 2, 1);
    const dim3 blocks(
        static_cast<unsigned int>((Wo + TILE_W - 1) / TILE_W),
        static_cast<unsigned int>((Ho + TILE_H - 1) / TILE_H),
        static_cast<unsigned int>(N * C));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(x_c.device().index());
    AT_DISPATCH_FLOATING_TYPES(
        x_c.scalar_type(),
        "depthwise_vertical_cuda",
        [&] {
            const size_t smem_bytes =
                stride == 1
                    ? static_cast<size_t>(TILE_W *
                                          (TILE_H + effective_k - 1)) *
                          sizeof(scalar_t)
                    : 0;
            depthwise_vertical_kernel<scalar_t><<<blocks, threads, smem_bytes, stream>>>(
                x_c.data_ptr<scalar_t>(),
                w_c.data_ptr<scalar_t>(),
                b_c.numel() ? b_c.data_ptr<scalar_t>() : nullptr,
                out.data_ptr<scalar_t>(),
                N,
                C,
                H,
                W,
                K,
                Ho,
                Wo,
                stride,
                padding,
                dilation,
                b_c.numel() != 0);
        });

    return out;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor depthwise_vertical_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation);

torch::Tensor depthwise_vertical(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    return depthwise_vertical_cuda(
        x, weight, bias, stride, padding, dilation);
}
"""

_depthwise_ext = load_inline(
    name="depthwise_vertical_cuda_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["depthwise_vertical"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv2d.bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )
        else:
            bias = self.conv2d.bias

        return _depthwise_ext.depthwise_vertical(
            x,
            self.conv2d.weight,
            bias,
            self.stride,
            self.padding,
            self.dilation,
        )

